ValidationRule.errorConditionFormula:
AND(
    NOT(ISBLANK(Target_Close_Date__c)),
    OR(
        AND(
            NOT(ISBLANK(Offer_Date__c)),
            Target_Close_Date__c < Offer_Date__c
        ),
        AND(
            NOT(ISBLANK(Offer_Expiration_Date__c)),
            Target_Close_Date__c < Offer_Expiration_Date__c
        )
    )
)
